		chattext1_ma = 'Kau masih sama, suka bercakap tentang lelaki dan perempuan.  ',
		chattext1_en = 'You\'re still the same, always talking about men and women.  ',
		chattext1_th = 'เจ้ายังเหมือนเดิม ชอบพูดเรื่องผู้ชาย ผู้หญิงอยู่เรื่อย',
		chattext1_in = 'Kau tetap sama, selalu bicara soal laki-laki dan perempuan.  ',
		chattext1_ph = 'Palagi kang ganyan, laging pinag-uusapan ang tungkol sa mga lalaki at babae.  ',
		chattext2_vn = 'Không ngờ ngươi yếu vậy, rõ ràng là nam nhân...',
		chattext2 = 'Can’t believe you’re this weak... and you’re supposed to be a man?',
		chattext2_ma = 'Tak sangka kau lemah begini, padahal kau lelaki...  ',
		chattext2_en = 'Can’t believe you’re this weak... and you’re supposed to be a man?',
