		chattext2_in = 'Tidak kusangka kau lemah seperti ini, padahal laki-laki...  ',
		chattext2_ph = 'Hindi ko akalain na ganito ka kahina, eh lalaki ka pa man din...  ',
		chattext3_vn = 'Được, ta sẽ quay về báo cho Gaara, bảo Làng Lá đã bồi dưỡng đời sau đáng tin cậy.',
		chattext3 = 'Alright, I’ll report back to Gaara and tell him the Hidden Leaf has raised a reliable next generation.  ',
		chattext3_ma = 'Baiklah, saya akan pulang beritahu Gaara, kata Hidden Leaf telah membesarkan generasi akan datang yang boleh dipercayai.  ',
		chattext3_en = 'Alright, I’ll report back to Gaara and tell him the Hidden Leaf has raised a reliable next generation.  ',
		chattext3_th = 'โอเค ฉันจะกลับไปบอกกาอาระว่าหมู่บ้านโคโนฮะได้ฝึกฝนรุ่นใหม่ที่ไว้ใจได้แล้ว',
		chattext3_in = 'Baik, aku akan kembali dan beri tahu Gaara bahwa Desa Daun telah membesarkan generasi penerus yang bisa diandalkan  ',
		chattext3_ph = 'Ayos, babalik ako at isasabi kay Gaara na maaasahan ang bagong henerasyon ng Konoha  '
	},
